{"command":"python3 - << 'PY'
import numpy as np, base64, struct, sys, json, os

def gen_pcm(wavetype, freq, duration, sr=44100):
    t = np.arange(int(sr*duration))/sr
    if wavetype=='square':
        wave = np.sign(np.sin(2*np.pi*freq*t))
    elif wavetype=='saw':
        wave = 2*(t*freq - np.floor(0.5 + t*freq))
    elif wavetype=='triangle':
        wave = 2*np.abs(2*(t*freq - np.floor(t*freq + 0.5))) - 1
    else:
        wave = np.sin(2*np.pi*freq*t)
    wave = np.int16(wave/np.max(np.abs(wave)) * 32767)
    return wave.tobytes()

samples = {
    'lead': gen_pcm('square', 440, 2.0),
    'bass': gen_pcm('saw', 110, 2.0),
    'noise': gen_pcm('square', 0, 0.5)  # zero freq generates flat? use random noise instead
}
# generate noise as random samples
noise = (np.random.rand(int(44100*0.2))*2-1)
noise = np.int16(noise/np.max(np.abs(noise))*32767)
samples['noise'] = noise.tobytes()

for name, data in samples.items():
    b64 = base64.b64encode(data).decode('ascii')
    open(f'/workspace/{name}.b64','w').write(b64)
print('samples written')
PY"}

